import { useMemo } from "react";

type ReactRef<T> = React.RefCallback<T> | React.MutableRefObject<T>;

export function assignRef<T>(ref: ReactRef<T> | null | undefined, value: T) {
  if (ref == null) return;

  if (typeof ref === "function") {
    ref(value);
    return;
  }

  try {
    ref.current = value;
  } catch {
    throw new Error(`Cannot assign value to ref. The ref object may be read-only.`);
  }
}

export function useMergeRefs<T>(...refs: (ReactRef<T> | null | undefined)[]) {
  return useMemo(
    () => (node: T | null) => {
      refs.forEach((ref) => {
        assignRef(ref, node);
      });
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    refs,
  );
}
